using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;
    vector<string> an(n);
    for (int i = 0; i < n; ++i) {
        cin >> an[i];
    }

    string as;
    for (int i = 0; i < n; ++i) {
        if (i) as += " ";
        as += an[i];
    }

    for (size_t pos = 0; pos < as.size(); ++pos) {
        if (as[pos] == ' ') as.insert(pos, " ");
    }

    as = " " + as + " ";

    int p = 1;
    for (int i = 0; i < n; ++i) {
        string pattern = " " + an[i] + " ";
        int q = 0;
        size_t pos = 0;
        while ((pos = as.find(pattern, pos)) != string::npos) {
            ++q;
            pos += pattern.size();
        }
        if (q > p) p = q;
    }

    cout << p;
    return 0;
}

