    int n = std::stoi(n_str);

    std::string as;
    if (!std::getline(std::cin, as)) return 0;

    std::stringstream ss(as);
    std::vector<std::string> an;
    std::string token;
    while (ss >> token) {
        an.push_back(token);
    }

    // Replace single spaces with double spaces
    std::string modified = as;
    for (size_t i = 0; i < modified.size(); ++i) {
        if (modified[i] == ' ') {
            modified.insert(i, " ");
            ++i;
        }
    }

    // Add leading and trailing space
    modified = " " + modified + " ";

    int p = 1;
    for (int i = 0; i < n && i < (int)an.size(); ++i) {
        std::string pattern = " " + an[i] + " ";
        int q = 0;
        size_t pos = 0;
        while ((pos = modified.find(pattern, pos)) != std::string::npos) {
            ++q;
            pos += pattern.size();
        }
        if (q > p) {
            p = q;
        }
    }

    std::cout << p;
    return 0;
}

